\section{Introduction}

\subsection{The problem}
Airy's equation
\begin{equation}\label{eq:airy}
  y'' = x\,y
\end{equation}
was introduced in 1838 in the study of light intensity near a caustic. It is the canonical model of a
\emph{turning point}: for $x<0$ its solutions oscillate with slowly decreasing wavelength, for $x>0$
they grow or decay exponentially, and the transition at $x=0$ governs phenomena from the supernumerary
rainbow to quantum tunnelling, from radio propagation past the horizon to edge scaling limits of random
matrix ensembles. Its solutions $\Ai$ and $\Bi$ are entire, but are not expressible in elementary closed
form. Our purpose is to make that impossibility precise and to prove the parts of it accessible by
finite algebraic means.

\subsection{What ``closed form'' means here}

\begin{definition}[EML expression]
The set of \emph{exponential--logarithmic} (EML) expressions is the smallest set of finite trees
containing the symbol $X$ and a symbol $\underline c$ for each real constant $c$, and closed under
$A+B$, $A\cdot B$, $A^{-1}$, $\exp A$, $\log A$.
\end{definition}

\begin{definition}[Interpretation]
The evaluation $\evalb{\cdot}\colon \EML \to (\mathbb{R}\to\mathbb{R})$ is defined recursively by
$\evalb{X}(x)=x$, $\evalb{\underline c}(x)=c$, $\evalb{A+B}=\evalb{A}+\evalb{B}$,
$\evalb{A\cdot B}=\evalb{A}\evalb{B}$, $\evalb{A^{-1}}(x)=\bigl(\evalb{A}(x)\bigr)^{-1}$,
$\evalb{\exp A}(x)=e^{\evalb{A}(x)}$, $\evalb{\log A}(x)=\log\evalb{A}(x)$, with the junk-value
conventions $0^{-1}=0$ and $\log t = 0$ for $t\le 0$ used outside the regular locus.
\end{definition}

\begin{definition}[Regularity]
The predicate $\Reg(E,x)$ is defined recursively: $\Reg(X,x)$ and $\Reg(\underline c,x)$ always hold;
$\Reg(A+B,x)$ and $\Reg(A\cdot B,x)$ hold iff $\Reg(A,x)$ and $\Reg(B,x)$; $\Reg(\exp A,x)$ iff
$\Reg(A,x)$; and $\Reg(A^{-1},x)$, resp.\ $\Reg(\log A,x)$, iff $\Reg(A,x)$ and $\evalb{A}(x)\neq 0$.
\end{definition}

Thus regularity says exactly that no inversion and no logarithm in the tree has vanishing argument.
The class of EML functions contains every function usually called elementary: $x^{a}=\exp(a\log x)$ on
$x>0$, roots, rational functions, and --- over the complexification --- the trigonometric and hyperbolic
families. Fixing the syntax is what allows one to quantify over \emph{all} closed forms at once.

\section{The differential calculus of EML expressions}

\begin{definition}[Symbolic derivative]\label{def:D}
Define $D\colon \EML\to\EML$ by
\[
  D(X)=\underline 1,\quad D(\underline c)=\underline 0,\quad D(A+B)=DA+DB,\quad
  D(A\cdot B)=(DA)\cdot B + A\cdot(DB),
\]
\[
  D(A^{-1})=\underline{(-1)}\cdot\bigl(DA\cdot(A^{-1}\cdot A^{-1})\bigr),\quad
  D(\exp A)=DA\cdot\exp A,\quad D(\log A)=DA\cdot A^{-1}.
\]
\end{definition}

Every right-hand side is again an EML expression: the class of closed forms is syntactically closed
under differentiation.

\begin{theorem}[Correctness of symbolic differentiation]\label{thm:correct}
If $\Reg(E,x)$ then $\evalb{E}$ is differentiable at $x$ and $\bigl(\evalb{E}\bigr)'(x)=\evalb{DE}(x)$.
\end{theorem}

\begin{proof}[Proof sketch]
Structural induction on $E$. The base cases are the derivatives of the identity and of a constant. Sums
and products use the sum and product rules together with the inductive hypotheses, available since
regularity of a sum or product is regularity of both parts. For $A^{-1}$, regularity supplies
$\evalb{A}(x)\neq 0$, so the reciprocal rule gives $-\evalb{DA}(x)/\evalb{A}(x)^{2}$, which is
$\evalb{D(A^{-1})}(x)$. For $\exp A$ and $\log A$ one composes with the inductive hypothesis, using
$\evalb{A}(x)\neq0$ in the logarithmic case.
\end{proof}

\begin{theorem}[Propagation of regularity]\label{thm:regprop}
If $\Reg(E,x)$ then $\Reg(DE,x)$.
\end{theorem}

\begin{proof}[Proof sketch]
Structural induction: every inversion or logarithm occurring in $DE$ occurs already in $E$ with the same
argument, and the inductive hypothesis covers the copies of $DA$ appearing inside.
\end{proof}

Theorems~\ref{thm:correct}--\ref{thm:regprop} give the working statement: an EML function may be
differentiated arbitrarily often on the regularity locus of the original expression, never leaving that
locus and never leaving the EML class.

\begin{theorem}[Exponentials solve first-order linear equations]\label{thm:firstorder}
If $\Reg(F,x)$ then $y=\exp\circ\evalb{F}$ satisfies $y'(x)=\evalb{DF}(x)\,y(x)$.
\end{theorem}

\begin{proof}[Proof sketch]
Apply Theorem~\ref{thm:correct} to $\exp F$, whose symbolic derivative is $DF\cdot\exp F$.
\end{proof}

\begin{theorem}[Uniqueness up to a constant]\label{thm:unique}
Let $F$ be regular at every real point and let $y\colon\mathbb{R}\to\mathbb{R}$ satisfy
$y'(x)=\evalb{DF}(x)y(x)$ for all $x$. Then $y(x)=K\,e^{\evalb{F}(x)}$ for a constant $K$.
\end{theorem}

\begin{proof}[Proof sketch]
Set $g(x)=y(x)e^{-\evalb{F}(x)}$. By Theorem~\ref{thm:correct} and the product rule,
$g'(x)=y'(x)e^{-\evalb{F}(x)}-\evalb{DF}(x)y(x)e^{-\evalb{F}(x)}=0$ for all $x$, so $g$ is constant,
say $g\equiv K$; multiply back by $e^{\evalb{F}(x)}$.
\end{proof}

Hence the first-order linear equation is completely solved, and all genuinely new phenomena begin in
order two.

\section{The Riccati correspondence}

\begin{theorem}[Linear $\Rightarrow$ Riccati]\label{thm:ric1}
Let $y$ be nowhere zero with $y'=u\,y$, $u'=w$ and $(uy)'=r\,y$. Then $w+u^{2}=r$ pointwise.
\end{theorem}

\begin{proof}[Proof sketch]
$y''=(uy)'=u'y+uy'=(w+u^{2})y$; comparing with $y''=ry$ gives $(w+u^{2}-r)y=0$, and $y$ never vanishes.
\end{proof}

\begin{theorem}[Riccati $\Rightarrow$ linear]\label{thm:ric2}
If $u'=w$, $w+u^{2}=r$ and $y'=uy$, then $(uy)'=ry$, i.e.\ $y''=ry$.
\end{theorem}

\begin{proof}[Proof sketch]
$(uy)'=u'y+uy'=wy+u^{2}y=ry$.
\end{proof}

\begin{lemma}[Logarithmic derivatives add]\label{lem:logderiv}
If $f,g$ are differentiable and nonzero at $x$, then
$(fg)'(x)=\bigl(f'(x)/f(x)+g'(x)/g(x)\bigr)f(x)g(x)$.
\end{lemma}

\begin{proof}[Proof sketch]
Product rule, then divide and multiply by $f(x)g(x)$.
\end{proof}

Lemma~\ref{lem:logderiv} is the group law behind the exponential parametrisation and the reason that a
\emph{product} of two solutions satisfies a manageable equation (Theorem~\ref{thm:symsq}).

\subsection{Kovacic's trichotomy}
For $y''=ry$ with $r$ rational, if some nonzero solution is Liouvillian then exactly one of the
following holds:
\begin{enumerate}
  \item[(1)] some solution has $y'/y\in\mathbb{C}(x)$;
  \item[(2)] case (1) fails but some product $y_1y_2$ of solutions lies in $\mathbb{C}(x)$, i.e.\ the
    second symmetric power equation has a rational solution;
  \item[(3)] all solutions are algebraic over $\mathbb{C}(x)$, of degree $4$, $6$ or $12$.
\end{enumerate}
Sections~\ref{sec:alg1}--\ref{sec:case1} eliminate case (1) for Airy; Section~\ref{sec:case2} eliminates
case~(2).

\section{Algebraic obstructions I: rational Riccati solutions}\label{sec:alg1}

Throughout, $K$ is a field, $p=\deg P$, $q=\deg Q$, and $\lc$ is the leading coefficient.

\begin{definition}
For $P,Q\in K[X]$ the \emph{Wronskian numerator} is $W(P,Q):=P'Q-PQ'$, the numerator of the derivative
of $P/Q$: $(P/Q)'=W(P,Q)/Q^{2}$.
\end{definition}

\begin{lemma}[Degree drop]\label{lem:degdrop}
For nonzero $A,B\in K[X]$ and $c\in K$, $\deg\bigl(A'B-c\,(AB')\bigr)<\deg A+\deg B$. In particular
$\deg W(P,Q)<p+q$.
\end{lemma}

\begin{proof}[Proof sketch]
$\deg A'<\deg A$ gives $\deg(A'B)<\deg A+\deg B$; symmetrically $\deg(AB')<\deg A+\deg B$; multiplying
by a constant cannot raise the degree; a difference has degree at most the maximum.
\end{proof}

\begin{lemma}[Top coefficient of $A'B$]\label{lem:topAB}
If $\deg A+\deg B\ge1$ then $[x^{\deg A+\deg B-1}](A'B)=(\deg A)\lc(A)\lc(B)$.
\end{lemma}

\begin{proof}[Proof sketch]
If $\deg A=0$ both sides vanish. Otherwise, $\deg A'\le\deg A-1$, so the coefficient of
$x^{(\deg A-1)+\deg B}$ in $A'B$ is $[x^{\deg A-1}]A'\cdot\lc(B)=(\deg A)\lc(A)\lc(B)$.
\end{proof}

\begin{proposition}[Top coefficient of the Wronskian numerator]\label{prop:topW}
$[x^{\,p+q-1}]W(P,Q)=(p-q)\lc(P)\lc(Q)$, where $p-q$ is read in $K$.
\end{proposition}

\begin{proof}[Proof sketch]
Apply Lemma~\ref{lem:topAB} to $P'Q$ and, after commuting factors, to $Q'P$, and subtract. If $p+q=0$
both sides vanish.
\end{proof}

\subsection{The odd-degree obstruction}
Clearing denominators in $u'+u^{2}=r$ with $u=P/Q$ gives
\begin{equation}\label{eq:riccati}
  P'Q-PQ'+P^{2}=r\,Q^{2}.
\end{equation}

\begin{theorem}[Odd-degree Riccati obstruction]\label{thm:odd}
If $r\in K[X]$ has odd degree, then \eqref{eq:riccati} has no solution with $Q\neq0$; equivalently
$u'+u^{2}=r$ has no solution in $K(x)$.
\end{theorem}

\begin{proof}[Proof sketch]
Oddness forces $r\neq0$. If $P=0$ then \eqref{eq:riccati} reads $0=rQ^{2}$, impossible. Assume
$P,Q\neq0$.

\emph{Case $q\le p$.} By Lemma~\ref{lem:degdrop}, $\deg W(P,Q)<p+q\le 2p=\deg P^{2}$, so the left side
has degree exactly $2p$, while the right has degree $\deg r+2q$. Hence $\deg r=2(p-q)$ is even, a
contradiction.

\emph{Case $p<q$.} Then $\deg W(P,Q)<p+q\le \deg r+2q$ and $\deg P^{2}=2p<\deg r+2q$, so the left side
has degree strictly below that of the right side, again a contradiction.
\end{proof}

\begin{corollary}[Airy Riccati]\label{cor:airyric}
$u'+u^{2}=x$ has no rational solution: $P'Q-PQ'+P^{2}\neq X Q^{2}$ for all $P$ and all $Q\neq0$.
\end{corollary}

\begin{theorem}[Degree and leading coefficient are forced]\label{thm:degdet}
If $0\neq u\in K[X]$ satisfies $u'+u^{2}=r$, then $\deg r = 2\deg u$ and $\lc(r)=\lc(u)^{2}$.
\end{theorem}

\begin{proof}[Proof sketch]
$\deg u'<\deg u\le 2\deg u=\deg u^{2}$, so $u^{2}$ dominates the sum $u'+u^{2}$ and dictates both its
degree and its leading coefficient.
\end{proof}

\begin{corollary}
$u'+u^{2}=x$ has no polynomial solution, since $1$ is not twice a natural number.
\end{corollary}

\subsection{No rational solutions of $y''=ry$}
The successive quotient-rule numerators of $v=P/Q$ are
\begin{equation}\label{eq:nums}
  v'=\frac{W}{Q^{2}},\qquad v''=\frac{B}{Q^{3}},\qquad v'''=\frac{Z}{Q^{4}},
\end{equation}
where $W=P'Q-PQ'$, $B=W'Q-2WQ'$ and $Z=B'Q-3BQ'$.

\begin{theorem}[No rational solutions]\label{thm:norational}
Let $r,P,Q\in K[X]$ be nonzero. Then $W'Q-2WQ'\neq r\,P\,Q^{2}$; i.e.\ $y''=ry$ has no nonzero rational
solution $y=P/Q$.
\end{theorem}

\begin{proof}[Proof sketch]
The displayed identity is $v''=rv$ cleared by $Q^{3}$. If $W=0$ the left side vanishes and the right does
not. Otherwise Lemma~\ref{lem:degdrop} twice gives $\deg(W'Q-2WQ')<\deg W+q<p+2q$, whereas the right
side has degree $\deg r+p+2q\ge p+2q$.
\end{proof}

\begin{corollary}
Airy's equation has no nonzero rational solution, in particular no nonzero polynomial solution.
\end{corollary}

\section{From algebra to analysis: Kovacic's first case fails for Airy}\label{sec:case1}

\begin{theorem}[No nowhere-vanishing solution has rational logarithmic derivative]\label{thm:analytic1}
Let $P,Q$ be real polynomials with $Q$ nowhere vanishing, and let $y\colon\mathbb{R}\to\mathbb{R}$ be
nowhere zero with $y'(x)=\tfrac{P(x)}{Q(x)}y(x)$ and $\bigl(\tfrac{P}{Q}y\bigr)'(x)=x\,y(x)$ for all $x$.
Then a contradiction follows.
\end{theorem}

\begin{proof}[Proof sketch]
The quotient rule gives $(P/Q)'=(P'Q-PQ')/Q^{2}$ pointwise. Uniqueness of derivatives applied to the two
expressions for $(uy)'$, $u=P/Q$, yields
\[
  \Bigl(x-\frac{P'Q-PQ'}{Q^{2}}(x)-\Bigl(\frac{P}{Q}(x)\Bigr)^{2}\Bigr)y(x)=0 ,
\]
and $y(x)\neq0$ forces the bracket to vanish for every real $x$. Multiplying by $Q(x)^{2}$ gives
$\bigl(P'Q-PQ'+P^{2}\bigr)(x)=\bigl(XQ^{2}\bigr)(x)$ for all real $x$; two real polynomials agreeing
everywhere are equal, contradicting Corollary~\ref{cor:airyric}.
\end{proof}

\begin{theorem}[Airy has no EML solution of exponential type]\label{thm:noEML}
Let $F$ be an EML expression regular at every real point with $\evalb{DF}=P/Q$, $Q$ nowhere vanishing.
Then $y=e^{\evalb{F}}$ does not solve $y''=x\,y$.
\end{theorem}

\begin{proof}[Proof sketch]
By Theorem~\ref{thm:firstorder}, $y'=(P/Q)y$, and $y$ is nowhere zero; if additionally $y''=xy$ then
Theorem~\ref{thm:analytic1} applies.
\end{proof}

\begin{proposition}[Sharpness]\label{prop:sharp}
For $r=x^{2}+1$ the Riccati equation $u'+u^{2}=r$ has the polynomial solution $u=x$; in cleared form
with $P=X$, $Q=1$, $\;P'Q-PQ'+P^{2}=1+X^{2}=(X^{2}+1)\cdot1^{2}$. Correspondingly $y=e^{x^{2}/2}$
satisfies $y'=xy$ and $y''=(x^{2}+1)y$, a genuine EML solution of exponential type.
\end{proposition}

\begin{proof}[Proof sketch]
$\frac{d}{dx}e^{x^{2}/2}=xe^{x^{2}/2}$, and $\frac{d}{dx}\bigl(xe^{x^{2}/2}\bigr)=(1+x^{2})e^{x^{2}/2}$.
\end{proof}

Thus the obstruction for Airy is exactly the \emph{parity} of $\deg r$.

\section{Kovacic's second case: the second symmetric power}\label{sec:case2}

\begin{theorem}[Second symmetric power]\label{thm:symsq}
Let $y_1,y_2$ satisfy $y_i''=r\,y_i$ with $r$ differentiable, and put $v=y_1y_2$. Then
\[
  v'=y_1'y_2+y_1y_2',\qquad v''=2y_1'y_2'+2r\,v,\qquad v'''=4r\,v'+2r'\,v .
\]
\end{theorem}

\begin{proof}[Proof sketch]
The first identity is the product rule. Differentiating and substituting $y_i''=ry_i$ gives
$v''=2y_1'y_2'+2rv$. Differentiating once more, $(2y_1'y_2')'=2(ry_1)y_2'+2y_1'(ry_2)=2rv'$ and
$(2rv)'=2r'v+2rv'$, so $v'''=4rv'+2r'v$.
\end{proof}

For Airy ($r=x$, $r'=1$) the symmetric square is
\begin{equation}\label{eq:symsq}
  v'''=4x\,v'+2v .
\end{equation}

\begin{theorem}[No polynomial solution]\label{thm:nopoly}
Over a field $K$ of characteristic zero, \eqref{eq:symsq} has no nonzero polynomial solution.
\end{theorem}

\begin{proof}[Proof sketch]
Let $n=\deg v$ and $\ell=\lc(v)\neq0$. Since $\deg v''\le n$, the coefficient formula for the derivative
gives $[x^{n}]v'''=(n+1)[x^{n+1}]v''=0$. On the right,
$[x^{n}](4Xv'+2v)=4[x^{n-1}]v'+2\ell=(4n+2)\ell$, which is nonzero because $4n+2$ is a positive integer
and $K$ has characteristic zero.
\end{proof}

\begin{definition}\label{def:core}
For $P,Q\in K[X]$ let $W,B,Z$ be as in \eqref{eq:nums} and set
\[
  \Phi(P,Q):=4X\,W+2PQ, \qquad \Psi(P,Q):=\Phi(P,Q)\,Q^{2}=4X\,W\,Q^{2}+2P\,Q^{3}.
\]
Then $v=P/Q$ solves \eqref{eq:symsq} if and only if $Z=\Psi(P,Q)$.
\end{definition}

\begin{lemma}[Degree of the cleared left-hand side]\label{lem:degZ}
For nonzero $P,Q$, $\deg Z<p+3q$.
\end{lemma}

\begin{proof}[Proof sketch]
Three applications of Lemma~\ref{lem:degdrop}: $\deg W<p+q$, $\deg B<\deg W+q<p+2q$ and
$\deg Z<\deg B+q<p+3q$; the degenerate cases $W=0$ (whence $B=Z=0$) and $B=0$ (whence $Z=0$) are
immediate.
\end{proof}

\begin{lemma}[Top coefficient of the core]\label{lem:topcore}
For nonzero $P,Q$, $\deg\Phi(P,Q)\le p+q$ and
$[x^{\,p+q}]\Phi(P,Q)=\bigl(4(p-q)+2\bigr)\lc(P)\lc(Q)$.
\end{lemma}

\begin{proof}[Proof sketch]
By Proposition~\ref{prop:topW}, $[x^{p+q-1}]W=(p-q)\lc(P)\lc(Q)$; multiplication by $X$ shifts the index
by one, so $[x^{p+q}](4XW)=4(p-q)\lc(P)\lc(Q)$, while $[x^{p+q}](2PQ)=2\lc(P)\lc(Q)$. The degree bound
follows from $\deg(XW)\le1+\deg W\le p+q$ and $\deg(PQ)=p+q$.
\end{proof}

\begin{lemma}[Top coefficient of the cleared right-hand side]\label{lem:toppsi}
Over a field of characteristic zero and for nonzero $P,Q$,
\[
  [x^{\,p+3q}]\Psi(P,Q)=\bigl(4(p-q)+2\bigr)\lc(P)\lc(Q)^{3}\neq0 .
\]
\end{lemma}

\begin{proof}[Proof sketch]
If $\deg f\le m$ then $[x^{m+\deg g}](fg)=[x^{m}]f\cdot\lc(g)$; apply this with $f=\Phi(P,Q)$,
$m=p+q$, $g=Q^{2}$ and use Lemma~\ref{lem:topcore}. Nonvanishing holds because $\lc(P),\lc(Q)\neq0$ and
$4k+2\neq0$ for every integer $k$.
\end{proof}

\begin{theorem}[No rational solution of the Airy symmetric square]\label{thm:norat2}
Over a field of characteristic zero and for nonzero $P,Q$, one has $Z\neq\Psi(P,Q)$; that is,
$v'''=4xv'+2v$ has no nonzero rational solution.
\end{theorem}

\begin{proof}[Proof sketch]
If $Z=\Psi(P,Q)$ then Lemma~\ref{lem:degZ} forces $[x^{p+3q}]Z=0$, contradicting
Lemma~\ref{lem:toppsi}.
\end{proof}

\begin{lemma}[Rational derivatives]\label{lem:ratderiv}
Let $P,Q$ be real polynomials with $Q$ nowhere vanishing and $W,B,Z$ as above. Then for all real $x$,
\[
  \Bigl(\tfrac{P}{Q}\Bigr)'(x)=\frac{W(x)}{Q(x)^{2}},\qquad
  \Bigl(\tfrac{W}{Q^{2}}\Bigr)'(x)=\frac{B(x)}{Q(x)^{3}},\qquad
  \Bigl(\tfrac{B}{Q^{3}}\Bigr)'(x)=\frac{Z(x)}{Q(x)^{4}} .
\]
\end{lemma}

\begin{proof}[Proof sketch]
Quotient rule; the denominator derivatives are $2QQ'$ and $3Q^{2}Q'$, and one factor of $Q$ cancels each
time.
\end{proof}

\begin{theorem}[Products of Airy solutions are never rational]\label{thm:capstone}
Let $y_1,y_2$ satisfy $y_i''=x\,y_i$ on $\mathbb{R}$, let $P,Q$ be real polynomials with $P\neq0$ and
$Q$ nowhere vanishing, and suppose $y_1(x)y_2(x)=P(x)/Q(x)$ for all $x$. Then a contradiction follows.
\end{theorem}

\begin{proof}[Proof sketch]
Put $v=y_1y_2$. Theorem~\ref{thm:symsq} with $r(x)=x$, $r'(x)=1$ gives $v'''=4xv'+2v$. On the other
hand $v=P/Q$, so Lemma~\ref{lem:ratderiv} and uniqueness of derivatives give, successively,
$v'=W/Q^{2}$, $v''=B/Q^{3}$ and $v'''=Z/Q^{4}$ pointwise. Substituting and multiplying by
$Q(x)^{4}\neq0$ yields $Z(x)=\Psi(P,Q)(x)$ for all real $x$, hence $Z=\Psi(P,Q)$ as polynomials,
contradicting Theorem~\ref{thm:norat2}.
\end{proof}

This is precisely the failure of Kovacic's second case for Airy's equation.

\section{Algorithms}

\subsection{Symbolic differentiation with regularity certification}
Represent an EML expression as a tree. Definition~\ref{def:D} computes $DE$ in time linear in the size
of $E$. Regularity at a point is checked by a bottom-up evaluation testing the argument of every
inversion and logarithm against zero, again linear. Theorems~\ref{thm:correct}--\ref{thm:regprop}
certify correctness and stability under iterated differentiation.

\subsection{The case-1 test for polynomial coefficients}
Given $r$: if $\deg r$ is odd, report ``no rational Riccati solution'' (Theorem~\ref{thm:odd}), an
$O(1)$ decision. If $\deg r=2m$, a polynomial Riccati solution must have degree $m$ and leading
coefficient a square root of $\lc(r)$ (Theorem~\ref{thm:degdet}); substituting
$u=\sum_{i\le m}c_ix^{i}$ into $u'+u^{2}=r$ determines $c_{m-1},c_{m-2},\dots$ successively by linear
equations with the nonzero multiplier $2c_m$, so the search costs $O(m^{2})$ field operations.

\subsection{The rational-solution test for $y''=ry$}
Compare $\deg(W'Q-2WQ')<p+2q$ with $\deg(rPQ^{2})=\deg r+p+2q$; for $r\neq0$ the comparison is always
strict (Theorem~\ref{thm:norational}), so the test is a constant-time degree comparison.

\subsection{The case-2 test for Airy}
For candidate degrees $p,q\ge0$, evaluate the obstruction constant $\kappa(p,q):=4(p-q)+2$. By
Lemmas~\ref{lem:degZ} and \ref{lem:toppsi}, $Z=\Psi(P,Q)$ would force $\kappa(p,q)\lc(P)\lc(Q)^{3}=0$;
in characteristic zero $\kappa(p,q)\neq0$ always, so the test rejects for every $(p,q)$ without any
search.

\section{Applications and interpretation}

Computer algebra systems attempt closed-form solving by exactly the strategy formalised here: encode
``closed form'' syntactically, reduce solvability to a rational-function question, and settle that
question by degree bookkeeping. An impossibility theorem is what allows such a solver to terminate with
certainty rather than search forever.

For Airy specifically, the absence of an elementary formula redirects effort to the representations that
do work: the everywhere-convergent series $y(x)=\sum_{n\ge0}a_nx^{n}$ with
$a_{n+3}=a_n/\bigl((n+3)(n+2)\bigr)$; the integral $\Ai(x)=\frac1\pi\int_0^{\infty}\cos\bigl(\frac{t^{3}}{3}+xt\bigr)dt$;
and the asymptotics $\Ai(x)\sim\frac{1}{2\sqrt\pi}x^{-1/4}e^{-\frac23x^{3/2}}$,
$\Ai(-x)\sim\frac{1}{\sqrt\pi}x^{-1/4}\sin\bigl(\frac23x^{3/2}+\frac\pi4\bigr)$ as $x\to+\infty$.

Physically, \eqref{eq:airy} is the local normal form of a Schr\"odinger operator near a classical
turning point: linearising a potential $V$ where $V(x_0)=E$ gives $\psi''=c(x-x_0)\psi$. The failure of
Kovacic's first two cases says that the turning-point connection problem is genuinely non-elementary,
explaining why the WKB approximation --- elementary on either side --- cannot be patched elementarily
across the turning point.

\begin{center}
\begin{tabular}{@{}lll@{}}
\toprule
Case & Cleared identity & Obstruction \\
\midrule
1 & $P'Q-PQ'+P^{2}=rQ^{2}$ & LHS degree even ($2p$) or too small; RHS degree $\deg r+2q$ odd \\
2 & $Z=(4XW+2PQ)Q^{2}$ & $[x^{p+3q}]$RHS $=\bigl(4(p-q)+2\bigr)\lc P\lc Q^{3}\neq0$; $\deg Z<p+3q$ \\
\bottomrule
\end{tabular}
\end{center}

In both rows the analytic content is converted into a statement about integers: $\deg r$ is odd, and
$4k+2\neq0$.

\section{Discussion and future directions}

The development establishes: a syntax for exponential--logarithmic functions with a verified symbolic
derivative; the complete solution theory of $y'=c\,y$; the degree and leading-coefficient determination
step for polynomial Riccati solutions; the non-existence of rational solutions of $u'+u^{2}=r$ for $r$
of odd degree; the non-existence of nonzero rational solutions of $y''=ry$ for $r\neq0$; the failure of
Kovacic's first case for Airy; and the failure of Kovacic's second case, namely that $v'''=4xv'+2v$ has
no nonzero polynomial or rational solution.

Natural next steps are: (1) Kovacic's third case, in which the solution is algebraic of degree $4$, $6$
or $12$, requiring a rationality test on the fourth and twelfth symmetric powers --- the pattern of
clearing denominators and comparing a top coefficient with a strict degree bound should transfer
verbatim; (2) a direct proof that no nonzero solution of $y''=xy$ is algebraic over $\mathbb{C}(x)$, by
pushing the Riccati equation into a finite extension and repeating the degree count with valuations;
(3) the identification of the differential Galois group of Airy's equation as $\mathrm{SL}_2$, for which
a lightweight substitute for full Picard--Vessiot theory is the Wronskian-determinant torsor on the
two-dimensional solution space; (4) Liouville's theorem for EML towers, which would express
``$e^{-x^{2}}$ has no EML antiderivative'' in the present framework; (5) extension of the odd-degree
obstruction from polynomial to rational $r$ via a local residue analysis $c^{2}=c$ at each simple pole;
and (6) assembly of these into a complete, certified implementation of Kovacic's algorithm.

\section{Conclusion}

Fixing a syntax for exponential--logarithmic functions and proving that symbolic differentiation is
analytically correct on the regularity locus turns ``there is no closed-form solution'' into a provable
statement. Within that framework the Riccati correspondence converts closed-form solvability of
$y''=ry$ into rational-function questions settled by degree counts. For Airy's equation the outcome is
decisive at the first two levels of Kovacic's trichotomy: no solution has a rational logarithmic
derivative, and no product of two solutions is a rational function. The mechanisms are the parity of
$2\deg Q+1$ and the non-vanishing of $4(\deg P-\deg Q)+2$ --- arithmetic modulo $2$ and $4$, which is
exactly what impossibility proofs in differential algebra are made of.

\end{document}

