"""Algorithm 1: symbolic differentiation of exponential-logarithmic expressions
with pointwise regularity certification."""

from __future__ import annotations

from dataclasses import dataclass
from typing import Callable, Tuple
import math


@dataclass(frozen=True)
class EML:
    """Expression tree over {x, constants, +, *, inv, exp, log}."""

    kind: str
    value: float = 0.0
    args: Tuple["EML", ...] = ()


def X() -> EML:
    """The variable."""
    return EML("X")


def const(c: float) -> EML:
    """A real constant."""
    return EML("const", value=float(c))


def add(a: EML, b: EML) -> EML:
    """Sum."""
    return EML("add", args=(a, b))


def mul(a: EML, b: EML) -> EML:
    """Product."""
    return EML("mul", args=(a, b))


def inv(a: EML) -> EML:
    """Reciprocal."""
    return EML("inv", args=(a,))


def exp_(a: EML) -> EML:
    """Exponential."""
    return EML("exp", args=(a,))


def log_(a: EML) -> EML:
    """Logarithm."""
    return EML("log", args=(a,))


def eml_eval(e: EML, x: float) -> float:
    """Interpret the expression as a real function (junk values off the regular locus)."""
    k = e.kind
    if k == "X":
        return x
    if k == "const":
        return e.value
    if k == "add":
        return eml_eval(e.args[0], x) + eml_eval(e.args[1], x)
    if k == "mul":
        return eml_eval(e.args[0], x) * eml_eval(e.args[1], x)
    if k == "inv":
        v = eml_eval(e.args[0], x)
        return 0.0 if v == 0.0 else 1.0 / v
    if k == "exp":
        return math.exp(eml_eval(e.args[0], x))
    if k == "log":
        v = eml_eval(e.args[0], x)
        return 0.0 if v <= 0.0 else math.log(v)
    raise ValueError(k)


def eml_regular(e: EML, x: float) -> bool:
    """Certify that every inversion and logarithm inside has nonzero argument at x."""
    k = e.kind
    if k in ("X", "const"):
        return True
    if k in ("add", "mul"):
        return eml_regular(e.args[0], x) and eml_regular(e.args[1], x)
    if k == "exp":
        return eml_regular(e.args[0], x)
    if k in ("inv", "log"):
        return eml_regular(e.args[0], x) and eml_eval(e.args[0], x) != 0.0
    raise ValueError(k)


def eml_D(e: EML) -> EML:
    """Symbolic derivative; the output is again an exponential-logarithmic expression."""
    k = e.kind
    if k == "X":
        return const(1.0)
    if k == "const":
        return const(0.0)
    if k == "add":
        return add(eml_D(e.args[0]), eml_D(e.args[1]))
    if k == "mul":
        a, b = e.args
        return add(mul(eml_D(a), b), mul(a, eml_D(b)))
    if k == "inv":
        a = e.args[0]
        return mul(const(-1.0), mul(eml_D(a), mul(inv(a), inv(a))))
    if k == "exp":
        a = e.args[0]
        return mul(eml_D(a), exp_(a))
    if k == "log":
        a = e.args[0]
        return mul(eml_D(a), inv(a))
    raise ValueError(k)


def certified_derivative(e: EML, x: float) -> float:
    """Return the derivative of the expression at x, refusing non-regular points."""
    if not eml_regular(e, x):
        raise ValueError("point is outside the regularity locus of the expression")
    return eml_eval(eml_D(e), x)


def _finite_difference(f: Callable[[float], float], x: float, h: float = 1e-5) -> float:
    """Fourth-order central difference, used only for validation."""
    return (f(x - 2 * h) - 8 * f(x - h) + 8 * f(x + h) - f(x + 2 * h)) / (12 * h)


if __name__ == "__main__":
    e = exp_(mul(X(), log_(add(X(), const(2.0)))))   # (x+2)^x
    for x in (0.5, 1.0, 2.0):
        s = certified_derivative(e, x)
        n = _finite_difference(lambda t: eml_eval(e, t), x)
        print(f"x={x:4.1f}  symbolic={s:.10f}  numeric={n:.10f}  |diff|={abs(s-n):.2e}")

algorithms.pseudocode:
input: polynomial r over a field of characteristic zero

if r = 0: return ('solution', u = 0)
if deg r is odd:
    return ('impossible-parity', none)      # no rational solution whatsoever

m <- deg r / 2
rho <- exact square root of lc(r)           # if none exists: no polynomial solution
for sign in {+1, -1}:
    c[m] <- sign * rho
    for j = m-1 down to 0:
        known <- [x^{m+j}] (derivative of current partial u)
                 + sum over i>j of c[i]*c[m+j-i]
        c[j]  <- ( [x^{m+j}] r  -  known ) / (2*c[m])
    u <- polynomial with coefficients c
    if derivative(u) + u^2 = r exactly:
        return ('solution', u)
return ('no-polynomial-solution', none)

